module.exports = get_theme

function get_theme() {
  return `
    :host {
      font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, sans-serif;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;

      --pale-blue: #6fa8dc;
      --pale-pink: #f4a6c0;
      --pale-green: #d1ece6;
      --sand: #f4efe6;
      --cream: #fbfaf6;
      --beige: #e9e6e1;
      --heather-dark: #8f64a4;
      --summer-yellow: #f7d879;
      --summer-strawberry: #e85f73;
      --summer-leaf: #7fbf8f;
      --ink: #2f4f4f;
      --muted: #6f8079;
      --line-soft: rgba(47, 79, 79, 0.1);
      --shadow-card: 0 16px 44px rgba(47, 79, 79, 0.075);
    }

    * {
      box-sizing: border-box;
    }

    [hidden] {
      display: none !important;
    }

    .page {
      overflow-x: hidden;
      background: var(--cream);
      color: var(--ink);
      line-height: 1.7;
    }

    h1,
    h2,
    h3,
    p {
      margin-top: 0;
    }

    h1 {
      max-width: 720px;
      margin: 0 0 1.25rem;
      color: var(--cream);
      font-size: clamp(2.35rem, 5vw, 4.6rem);
      font-weight: 750;
      line-height: 0.98;
      letter-spacing: -0.06em;
    }

    h2 {
      margin: 0 0 1.5rem;
      font-size: clamp(2rem, 4vw, 3.4rem);
      line-height: 1.05;
      letter-spacing: -0.045em;
    }

    h3 {
      margin: 0 0 0.55rem;
      color: var(--ink);
      font-size: 1.22rem;
      line-height: 1.18;
      letter-spacing: -0.02em;
    }

    p {
      margin-bottom: 1.15rem;
      font-size: 1.08rem;
      line-height: 1.72;
    }

    a {
      color: var(--heather-dark);
      text-underline-offset: 0.18em;
    }

    .eyebrow {
      margin-bottom: 0.9rem;
      color: rgba(255, 255, 255, 0.86);
      font-size: 0.76rem;
      font-weight: 800;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .eyebrow.dark {
      color: var(--heather-dark);
    }

    button,
    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      margin: 1rem 0;
      padding: 1rem 2.1rem;
      border: none;
      border-radius: 999px;
      background: var(--pale-pink);
      box-shadow: 0 14px 35px rgba(143, 100, 164, 0.22);
      color: white;
      cursor: pointer;
      font: inherit;
      font-size: 1rem;
      font-weight: 800;
      line-height: 1.1;
      text-decoration: none;
      transition:
        background 0.25s ease,
        color 0.25s ease,
        transform 0.25s ease;
    }

    button:hover,
    .button:hover {
      background: var(--heather-dark);
      transform: translateY(-1px);
    }

    button:focus-visible,
    .button:focus-visible,
    a:focus-visible {
      outline: 3px solid rgba(143, 100, 164, 0.4);
      outline-offset: 3px;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.85rem;
    }

    .hero-actions button,
    .hero-actions .button {
      margin-right: 0;
    }

    .wave {
      display: block;
      width: 100%;
      height: 118px;
      margin: -1px 0;
      line-height: 0;
    }

    .wave svg {
      display: block;
      width: 100%;
      height: 100%;
    }

    .section {
      padding: 5rem 1.5rem;
    }

    .light {
      background: var(--sand);
    }

    .soft {
      background: var(--pale-green);
    }

    .content {
      max-width: 960px;
      margin: 0 auto;
      letter-spacing: 0.1px;
    }

    .content p + p {
      margin-top: -0.35rem;
    }

    .content-wide {
      max-width: 1320px;
      margin: 0 auto;
    }

    .content-xl {
      max-width: 1480px;
      margin: 0 auto;
    }

    .content-split {
      display: grid;
      grid-template-columns: 0.85fr 1.15fr;
      align-items: start;
      gap: 4rem;
      max-width: 1180px;
    }

    .center {
      text-align: center;
    }

    .center p {
      max-width: 720px;
      margin-left: auto;
      margin-right: auto;
    }

    .section-intro {
      max-width: 720px;
      margin: 0 auto 2.2rem;
      font-size: 1.08rem;
      line-height: 1.62;
    }

    .photo {
      display: block;
      width: 100%;
      max-width: 820px;
      height: 560px;
      margin: 2rem auto;
      border: 14px solid rgba(255, 255, 255, 0.72);
      border-radius: 28px;
      background: white;
      box-shadow: 0 24px 70px rgba(47, 79, 79, 0.12);
      object-fit: cover;
      object-position: center 30%;
    }

    .swap-section .photo {
      width: auto;
      object-fit: contain;
    }

    .photo-strip {
      padding: 0 1.5rem 4rem;
      background: var(--beige);
    }

    .photo-strip .photo {
      margin: 0 auto;
      border-color: var(--cream);
    }

    /* Hero */

    .hero {
      padding: 3rem 1.5rem 1rem;
      background: var(--pale-blue);
      text-align: left;
    }

    .hero-inner {
      display: grid;
      grid-template-columns: minmax(0, 680px) minmax(320px, 540px);
      align-items: center;
      justify-content: center;
      gap: 4rem;
      max-width: 1320px;
      margin: 0 auto;
    }

    .hero-copy {
      padding: 2rem 0 4rem;
    }

    .logo img {
      height: 340px;
      margin-bottom: 2rem;
      filter: drop-shadow(0 2px 6px rgba(0, 0, 0, 0.08));
    }

    .hero .logo img {
      opacity: 0.96;
      filter:
        brightness(0)
        invert(1)
        drop-shadow(0 2px 10px rgba(0, 0, 0, 0.08));
    }

    .hero-subtitle {
      max-width: 600px;
      margin-bottom: 1rem;
      color: var(--cream);
      font-size: clamp(1.18rem, 2vw, 1.5rem);
      line-height: 1.45;
    }

    .hero-photo {
      width: 100%;
      max-width: 540px;
      margin: 0 auto;
      padding: 16px;
      overflow: hidden;
      border: 14px solid rgba(255, 255, 255, 0.75);
      border-radius: 44px;
      background: rgba(255, 255, 255, 0.2);
      box-shadow: 0 28px 80px rgba(47, 79, 79, 0.16);
      transform: rotate(-1deg);
    }

    .hero-photo .photo {
      display: block;
      width: 100%;
      max-width: none;
      height: 560px;
      margin: 0;
      border: none;
      border-radius: 28px;
      box-shadow: none;
      object-fit: cover;
    }

    /* Location */

    .location-section {
      background: var(--sand);
    }

    .location-section h2 {
      max-width: 760px;
      margin-left: auto;
      margin-right: auto;
    }

    .location-intro {
      max-width: 760px;
      margin: 0 auto 1rem;
      font-size: 1.18rem;
    }

    .location-tagline {
      max-width: 720px;
      margin: 0 auto 3rem;
      font-size: 1.18rem;
      font-weight: 500;
    }

    .location-visuals {
      display: grid;
      grid-template-columns: minmax(0, 1.35fr) minmax(0, 0.85fr);
      align-items: center;
      gap: 2rem;
      max-width: 1040px;
      margin: 0 auto 2.25rem;
    }

    .location-card {
      display: flex;
      align-items: center;
      justify-content: center;
      aspect-ratio: 4 / 3;
      overflow: hidden;
      border: 10px solid rgba(255, 255, 255, 0.82);
      border-radius: 28px;
      background: #f8f2e8;
      box-shadow: 0 20px 55px rgba(47, 79, 79, 0.09);
    }

    .location-card img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
      object-position: center;
    }

    .building-card,
    .map-card {
      padding: 0;
      background: #f8f2e8;
    }

    .map-card {
      aspect-ratio: 4 / 5;
    }

    .map-card img {
      object-fit: contain;
      object-position: center;
    }

    .location-line {
      max-width: 720px;
      margin: 0 auto;
      color: var(--muted);
      font-size: 1.12rem;
    }

    /* Purpose and photo sections */

    .small-purpose {
      background: var(--cream);
    }

    .photo-story {
      padding: 1rem 1.5rem 3.5rem;
      background: var(--cream);
    }

    .photo-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1.5rem;
    }

    .story-photo {
      display: block;
      width: 100%;
      height: 420px;
      border: 8px solid rgba(255, 255, 255, 0.7);
      border-radius: 26px;
      box-shadow: 0 18px 50px rgba(47, 79, 79, 0.1);
      object-fit: cover;
      transition: transform 0.25s ease;
    }

    .story-photo:hover {
      transform: translateY(-3px);
    }

    .relief-section,
    .swap-section {
      background: var(--pale-green);
    }

    .relief-section p:not(.eyebrow) {
      max-width: 820px;
      font-size: 1.2rem;
    }

    /* Included cards */

    .included-section {
      background: var(--sand);
    }

    .included-intro {
      max-width: 700px;
      margin: 0 auto 2rem;
    }

    .included-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1.25rem;
      margin-top: 2rem;
    }

    .included-card {
      padding: 1.65rem;
      border: 1px solid rgba(47, 79, 79, 0.1);
      border-radius: 24px;
      background: white;
      box-shadow: var(--shadow-card);
      text-align: left;
    }

    .included-card h3 {
      margin-bottom: 0.65rem;
      font-size: 1.12rem;
    }

    .included-card p {
      margin: 0;
      color: var(--muted);
      font-size: 0.98rem;
      line-height: 1.58;
    }

    /* Weekly calendar */

    .weekly-calendar-section {
      position: relative;
      padding-right: 1rem;
      padding-left: 1rem;
      background: var(--cream);
    }

    .weekly-calendar-section .content-wide {
      max-width: 1600px;
    }

    .weekly-calendar-section h2 {
      max-width: 820px;
      margin-left: auto;
      margin-right: auto;
    }

    .weekly-calendar-section .section-intro {
      max-width: 790px;
      margin-bottom: 1.5rem;
    }

    .calendar-legend {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: center;
      gap: 0.75rem 1.35rem;
      margin: 1.8rem auto 2.5rem;
      color: var(--muted);
    }

    .calendar-key {
      display: inline-flex;
      align-items: center;
      gap: 0.48rem;
      font-size: 0.86rem;
      font-weight: 750;
      line-height: 1.3;
    }

    .calendar-key-dot {
      width: 11px;
      height: 11px;
      flex: 0 0 11px;
      border-radius: 50%;
    }

    .public-dot {
      background: var(--pale-blue);
    }

    .member-dot {
      background: var(--pale-pink);
    }

    .flexible-dot {
      border: 1px solid rgba(47, 79, 79, 0.16);
      background: var(--pale-green);
    }

    .calendar-scroll {
      width: 100%;
      padding-bottom: 0.8rem;
      overflow-x: auto;
      scrollbar-width: thin;
      scrollbar-color:
        rgba(47, 79, 79, 0.24)
        rgba(47, 79, 79, 0.06);
      -webkit-overflow-scrolling: touch;
    }

    .calendar-scroll:focus-visible {
      outline: 3px solid rgba(143, 100, 164, 0.3);
      outline-offset: 5px;
      border-radius: 24px;
    }

    .calendar-scroll::-webkit-scrollbar {
      height: 8px;
    }

    .calendar-scroll::-webkit-scrollbar-track {
      border-radius: 999px;
      background: rgba(47, 79, 79, 0.06);
    }

    .calendar-scroll::-webkit-scrollbar-thumb {
      border-radius: 999px;
      background: rgba(47, 79, 79, 0.24);
    }

    .week-calendar {
      width: 100%;
      min-width: 1435px;
      max-width: 1600px;
      margin: 0 auto;
      overflow: hidden;
      border: 1px solid rgba(47, 79, 79, 0.14);
      border-radius: 24px;
      background: white;
      box-shadow: 0 16px 42px rgba(47, 79, 79, 0.07);
      text-align: left;
    }

    .calendar-header-row,
    .calendar-body-row {
      display: grid;
      grid-template-columns: repeat(7, minmax(205px, 1fr));
    }

    .calendar-header-row {
      border-bottom: 1px solid rgba(47, 79, 79, 0.13);
      background: var(--sand);
    }

    .calendar-day-heading {
      padding: 1rem 1.1rem;
      border-right: 1px solid rgba(47, 79, 79, 0.12);
      color: var(--ink);
      font-size: 0.78rem;
      font-weight: 850;
      line-height: 1;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .calendar-day-heading:last-child {
      border-right: none;
    }

    .public-heading {
      background: rgba(111, 168, 220, 0.15);
      color: #456f92;
    }

    .weekend-heading {
      background: rgba(209, 236, 230, 0.34);
    }

    .calendar-body-row {
      min-height: 0;
      align-items: stretch;
    }

    .calendar-day-cell {
      position: relative;
      isolation: isolate;
      display: grid;
      grid-template-columns: minmax(0, 1fr);
      grid-template-rows: repeat(60, 11px);
      grid-auto-rows: 11px;
      align-content: start;
      min-height: 660px;
      padding: 0.65rem;
      border-right: 1px solid rgba(47, 79, 79, 0.11);
      background-color: rgba(255, 255, 255, 0.94);
      background-image:
        repeating-linear-gradient(
          to bottom,
          transparent 0,
          transparent 43px,
          rgba(47, 79, 79, 0.07) 43px,
          rgba(47, 79, 79, 0.07) 44px
        );
    }

    .calendar-day-cell:last-child {
      border-right: none;
    }

    .public-cell {
      background-color: rgba(111, 168, 220, 0.035);
    }

    .weekend-cell {
      background-color: rgba(244, 239, 230, 0.42);
    }

    /*
     * Every event occupies the same grid column.
     * The full-day access event sits behind timed social events.
     */

    .week-event {
      position: relative;
      z-index: 1;
      display: block;
      grid-column: 1;
      grid-row: var(--row-start, 1) / var(--row-end, 2);
      align-self: stretch;
      width: auto;
      min-width: 0;
      max-width: none;
      min-height: 0;
      margin: 1px 0;
      padding: 0.34rem 0.46rem;
      overflow: hidden;
      border-radius: 12px;
      box-shadow: none;
      color: var(--ink);
      cursor: pointer;
      font: inherit;
      text-align: left;
      transform: none;
      appearance: none;
      -webkit-appearance: none;
    }

    .week-event:hover {
      box-shadow: none;
      transform: none;
      filter: brightness(0.98);
    }

    .week-event:focus-visible {
      z-index: 4;
      outline: 3px solid rgba(143, 100, 164, 0.44);
      outline-offset: 2px;
    }

    .member-event {
      border: 1px solid rgba(244, 166, 192, 0.76);
      background: rgba(244, 166, 192, 0.94);
    }

    .member-event:hover {
      background: var(--pale-pink);
    }

    .public-event {
      border: 1px solid rgba(77, 128, 173, 0.35);
      background: var(--pale-blue);
      color: white;
    }

    .public-event:hover {
      background: #639ed3;
    }

    .flexible-event {
      border: 1px dashed rgba(47, 79, 79, 0.18);
      background: rgba(209, 236, 230, 0.28);
    }

    .flexible-event:hover {
      background: rgba(209, 236, 230, 0.42);
    }

    /* Full-day flexible-access layer */

    .availability-event {
      z-index: 0;
      grid-column: 1;
      display: flex;
      width: 100%;
      flex-direction: column;
      align-items: flex-start;
      justify-content: flex-start;
      margin: 0;
      padding: 0.7rem 0.75rem;
      border: 1px dashed rgba(47, 79, 79, 0.16);
      border-radius: 14px;
      background: rgba(209, 236, 230, 0.24);
      box-shadow: none;
    }

    .availability-event:hover {
      background: rgba(209, 236, 230, 0.38);
      box-shadow: none;
      filter: none;
    }

    .availability-event .week-event-time {
      margin-bottom: 0.12rem;
      color: var(--muted);
      font-size: 0.61rem;
    }

    .availability-event .week-event-title {
      color: var(--ink);
      font-size: 0.72rem;
      line-height: 1.1;
    }

    /* Timed event layer */

    .social-event {
      z-index: 2;
      grid-column: 1;
      width: auto;
      margin: 2px 0.42rem;
      box-shadow: 0 6px 18px rgba(47, 79, 79, 0.14);
    }


    .social-event:hover {
      box-shadow: 0 8px 22px rgba(47, 79, 79, 0.18);
    }

    .weekend-cell .availability-event {
      background: rgba(209, 236, 230, 0.54);
    }

    .weekend-cell .availability-event:hover {
      background: rgba(209, 236, 230, 0.72);
    }

    .week-event-time {
      display: block;
      margin-bottom: 0.1rem;
      color: var(--heather-dark);
      font-size: 0.62rem;
      font-weight: 850;
      line-height: 1.05;
      letter-spacing: 0.01em;
    }

    .week-event-extra {
      display: block;
      margin-top: 0.12rem;
      font-size: 0.52rem;
      font-weight: 700;
      line-height: 1.08;
      opacity: 0.82;
    }

    .week-event-extra + .week-event-extra {
      margin-top: 0.05rem;
    }

    .week-event-title {
      display: block;
      margin: 0;
      color: var(--ink);
      font-size: 0.76rem;
      font-weight: 800;
      line-height: 1.03;
      letter-spacing: -0.01em;
      overflow-wrap: break-word;
    }

    .public-event .week-event-time,
    .public-event .week-event-title,
    .public-event .week-event-extra {
      color: white;
    }

    .calendar-summary {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      align-items: center;
      gap: 1.5rem;
      max-width: 1000px;
      margin: 2rem auto 2rem;
      padding: 1.25rem 1.35rem;
      border: 1px solid rgba(47, 79, 79, 0.08);
      border-radius: 20px;
      background: rgba(209, 236, 230, 0.48);
      text-align: left;
    }

    .calendar-summary p {
      max-width: none;
      margin: 0;
      color: var(--muted);
      font-size: 0.96rem;
      line-height: 1.55;
    }

    .calendar-summary strong {
      color: var(--ink);
    }

    .calendar-pass-link {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 44px;
      padding: 0.7rem 1rem;
      border: 1px solid rgba(143, 100, 164, 0.2);
      border-radius: 999px;
      background: white;
      color: var(--heather-dark);
      font-size: 0.88rem;
      font-weight: 850;
      line-height: 1.25;
      text-align: center;
      text-decoration: none;
      white-space: nowrap;
      transition:
        background 0.2s ease,
        color 0.2s ease,
        transform 0.2s ease;
    }

    .calendar-pass-link:hover {
      background: var(--heather-dark);
      color: white;
      transform: translateY(-1px);
    }

  /* Event modal */

  .event-modal {
    position: fixed;
    z-index: 10000;
    inset: 0;
    display: grid;
    place-items: center;
    padding: 1rem;
    text-align: left;
  }

  .event-modal-backdrop {
    position: absolute;
    inset: 0;
    display: block;
    width: 100%;
    height: 100%;
    max-width: none;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: rgba(30, 48, 48, 0.6);
    box-shadow: none;
    cursor: default;
    transform: none;
    appearance: none;
    -webkit-appearance: none;
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
  }

  .event-modal-backdrop:hover,
  .event-modal-backdrop:focus {
    background: rgba(30, 48, 48, 0.6);
    box-shadow: none;
    transform: none;
  }

  .event-modal-panel {
    position: relative;
    z-index: 1;
    width: min(520px, 100%);
    max-height: calc(100dvh - 2rem);
    padding: 1.75rem;
    overflow-y: auto;
    overscroll-behavior: contain;
    border: 1px solid rgba(47, 79, 79, 0.1);
    border-radius: 26px;
    background: var(--cream);
    box-shadow: 0 30px 90px rgba(22, 42, 42, 0.34);
    color: var(--ink);
    text-align: left;
    scrollbar-width: thin;
  }

  .event-modal-close {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
    display: grid;
    width: 40px;
    height: 40px;
    min-width: 40px;
    max-width: 40px;
    margin: 0;
    padding: 0;
    place-items: center;
    border: 0;
    border-radius: 50%;
    background: rgba(47, 79, 79, 0.07);
    box-shadow: none;
    color: var(--ink);
    cursor: pointer;
    font-size: 1.55rem;
    font-weight: 500;
    line-height: 1;
    transform: none;
    appearance: none;
    -webkit-appearance: none;
  }

  .event-modal-close:hover {
    background: rgba(47, 79, 79, 0.14);
    box-shadow: none;
    color: var(--ink);
    transform: none;
  }

  .event-modal-close:focus-visible {
    outline: 3px solid rgba(143, 100, 164, 0.4);
    outline-offset: 2px;
  }

  .event-modal-time {
    max-width: none;
    margin: 0 3.25rem 0.35rem 0;
    color: var(--heather-dark);
    font-size: 0.86rem;
    font-weight: 850;
    line-height: 1.3;
  }

  .event-modal-panel h3 {
    margin: 0 3.25rem 0.65rem 0;
    color: var(--ink);
    font-size: 1.55rem;
    line-height: 1.12;
  }

  .event-modal-access {
    display: flex;
    width: auto;
    max-width: none;
    align-items: flex-start;
    gap: 0.5rem;
    margin: 0 0 1.15rem;
    padding: 0;
    border-radius: 0;
    background: transparent;
    color: var(--muted);
    font-size: 0.8rem;
    font-weight: 750;
    line-height: 1.4;
  }

  .event-modal-access::before {
    content: "";
    width: 8px;
    height: 8px;
    flex: 0 0 8px;
    align-self: center;
    margin-top: 0;
    border-radius: 50%;
    background: var(--pale-pink);
  }

  .event-modal-description {
    max-width: none;
    margin: 0;
    color: var(--muted);
    font-size: 0.96rem;
    line-height: 1.5;
  }

  .event-modal-actions {
    display: grid;
    gap: 0.7rem;
    margin-top: 1rem;
  }

  .event-modal-actions[hidden] {
    display: none;
  }

  .event-modal-invitation {
    max-width: none;
    margin: 0 0 0.1rem;
    color: var(--ink);
    font-size: 0.92rem;
    line-height: 1.42;
  }

  .event-modal-actions .button {
    display: flex;
    width: 100%;
    max-width: none;
    min-height: 0;
    margin: 0;
    padding: 0.82rem 1rem;
    font-size: 0.92rem;
    line-height: 1.2;
    text-align: center;
  }

  .event-modal-pass {
    border: 2px solid var(--pale-pink);
    background: transparent;
    box-shadow: none;
    color: var(--heather-dark);
  }

  .event-modal-pass:hover {
    background: var(--pale-pink);
    color: white;
  }

    /* Reviews and press */

    .reviews-section {
      background: var(--pale-blue);
      color: white;
    }

    .reviews-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1.25rem;
      margin-top: 2rem;
    }

    .review-card {
      padding: 1.65rem;
      border: 1px solid rgba(47, 79, 79, 0.1);
      border-radius: 26px;
      background: var(--sand);
      box-shadow: var(--shadow-card);
      text-align: left;
    }

    .review-card p {
      max-width: none;
      margin: 0 0 1rem;
      color: var(--ink);
      font-size: 1rem;
      line-height: 1.6;
    }

    .review-card span {
      display: block;
      color: var(--muted);
      font-size: 0.82rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .press-mentions {
      max-width: 920px;
      margin: 3.5rem auto 0;
      padding-top: 2.75rem;
      border-top: 1px solid rgba(255, 255, 255, 0.32);
    }

    .press-eyebrow {
      margin-bottom: 0.7rem;
      color: rgba(255, 255, 255, 0.88);
      font-size: 0.76rem;
      font-weight: 800;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .press-intro {
      max-width: 690px;
      margin: 0 auto 1.75rem;
      color: white;
      font-size: 1.08rem;
      line-height: 1.6;
    }

    .press-links {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 1.25rem;
    }

    .press-link {
      display: flex;
      min-height: 190px;
      flex-direction: column;
      align-items: flex-start;
      padding: 1.65rem;
      border: 1px solid rgba(47, 79, 79, 0.1);
      border-radius: 24px;
      background: var(--sand);
      box-shadow: var(--shadow-card);
      color: var(--ink);
      text-align: left;
      text-decoration: none;
      transition:
        box-shadow 0.2s ease,
        transform 0.2s ease;
    }

    .press-link:hover {
      box-shadow: 0 20px 52px rgba(47, 79, 79, 0.14);
      transform: translateY(-2px);
    }

    .press-publication {
      display: block;
      margin-bottom: 0.8rem;
      color: var(--heather-dark);
      font-size: 0.76rem;
      font-weight: 850;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .press-title {
      display: block;
      margin-bottom: 1.25rem;
      color: var(--ink);
      font-size: 1.18rem;
      font-weight: 750;
      line-height: 1.35;
    }

    .press-read {
      display: block;
      margin-top: auto;
      color: var(--heather-dark);
      font-size: 0.94rem;
      font-weight: 800;
    }

    /* Summer pass */

    .pricing-section {
      background: var(--pale-green);
    }

    .summer-pricing-section {
      background:
        radial-gradient(
          circle at 14% 10%,
          rgba(247, 216, 121, 0.4) 0,
          rgba(247, 216, 121, 0.4) 110px,
          transparent 112px
        ),
        radial-gradient(
          circle at 87% 18%,
          rgba(244, 166, 192, 0.28) 0,
          rgba(244, 166, 192, 0.28) 96px,
          transparent 98px
        ),
        linear-gradient(180deg, var(--pale-green), #dff3ee);
    }

    .pricing-section .section-intro {
      max-width: 660px;
      margin: 0 auto 2rem;
      color: var(--ink);
      font-size: 1.05rem;
      line-height: 1.62;
    }

    .price-card {
      position: relative;
      padding: 1.8rem;
      border: 1px solid var(--line-soft);
      border-radius: 26px;
      background: rgba(255, 255, 255, 0.94);
      box-shadow: var(--shadow-card);
      font-size: 1rem;
      text-align: left;
    }

    .price-card h3 {
      margin: 0.5rem 0 0.75rem;
      font-size: 1.32rem;
    }

    .featured {
      border: 3px solid var(--pale-pink);
      box-shadow: 0 22px 58px rgba(244, 166, 192, 0.18);
    }

    .summer-offer-card {
      isolation: isolate;
      max-width: 660px;
      margin: 2rem auto 1.2rem;
      padding: 2.15rem;
      overflow: hidden;
      border: 3px solid rgba(244, 166, 192, 0.82);
      border-radius: 34px;
      background:
        linear-gradient(
          135deg,
          rgba(255, 255, 255, 0.96),
          rgba(251, 250, 246, 0.96)
        ),
        var(--cream);
      box-shadow: 0 26px 68px rgba(47, 79, 79, 0.13);
      text-align: left;
    }

    .summer-offer-card::before {
      content: "";
      position: absolute;
      z-index: -1;
      inset: 0;
      background:
        radial-gradient(
          circle at 16% 18%,
          rgba(247, 216, 121, 0.22) 0,
          rgba(247, 216, 121, 0.22) 84px,
          transparent 86px
        ),
        radial-gradient(
          circle at 88% 82%,
          rgba(209, 236, 230, 0.55) 0,
          rgba(209, 236, 230, 0.55) 120px,
          transparent 122px
        );
    }

    .summer-offer-card h3 {
      margin: 0.5rem 0 0.75rem;
      font-size: 1.82rem;
      line-height: 1.06;
    }

    .summer-card-intro {
      max-width: none;
      margin: 0 0 1rem;
      color: var(--muted);
    }

    .summer-total {
      margin: 1rem 0 0;
      padding: 1.35rem;
      border: 1px solid rgba(47, 79, 79, 0.08);
      border-radius: 24px;
      background: rgba(255, 255, 255, 0.72);
      text-align: center;
    }

    .summer-activation-note {
      margin-top: 1rem;
      margin-bottom: 0.9rem;
    }

    .summer-button {
      width: 100%;
      margin: 0.75rem 0 0;
      background: var(--summer-strawberry);
      box-shadow: 0 15px 38px rgba(232, 95, 115, 0.24);
    }

    .summer-button:hover {
      background: var(--heather-dark);
    }

    .summer-after-note {
      max-width: 620px;
      margin: 1rem auto 0;
      color: var(--muted);
      font-size: 0.98rem;
      line-height: 1.55;
    }

    .summer-shape {
      position: absolute;
      z-index: 0;
      pointer-events: none;
    }

    .summer-sun {
      top: 1.1rem;
      right: 1.1rem;
      width: 64px;
      height: 64px;
      border-radius: 50%;
      background: var(--summer-yellow);
      box-shadow: 0 0 0 12px rgba(247, 216, 121, 0.23);
      opacity: 0.78;
    }

    .summer-strawberry-one,
    .summer-strawberry-two {
      width: 28px;
      height: 34px;
      border-radius: 55% 55% 60% 60%;
      background: var(--summer-strawberry);
      opacity: 0.78;
      transform: rotate(-16deg);
    }

    .summer-strawberry-one::before,
    .summer-strawberry-two::before {
      content: "";
      position: absolute;
      top: -8px;
      left: 7px;
      width: 14px;
      height: 10px;
      border-radius: 60% 60% 30% 30%;
      background: var(--summer-leaf);
    }

    .summer-strawberry-one::after,
    .summer-strawberry-two::after {
      content: "";
      position: absolute;
      inset: 7px 8px;
      background:
        radial-gradient(
          circle,
          rgba(255, 255, 255, 0.65) 0 1.2px,
          transparent 1.4px
        );
      background-size: 8px 8px;
    }

    .summer-strawberry-one {
      bottom: 1.5rem;
      left: 1.25rem;
    }

    .summer-strawberry-two {
      right: 5.8rem;
      bottom: 2.2rem;
      opacity: 0.58;
      transform: rotate(14deg) scale(0.82);
    }

    .membership-total {
      margin: 1rem 0 0;
      padding: 1.25rem;
      border: 1px solid rgba(47, 79, 79, 0.08);
      border-radius: 22px;
      background: var(--cream);
      text-align: center;
    }

    .membership-total-label {
      display: inline-block;
      margin: 0;
      color: var(--muted);
      font-size: 0.78rem;
      font-weight: 850;
      line-height: 1.1;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .membership-total-price {
      display: block;
      margin-top: 0.45rem;
      color: var(--ink);
      font-size: 3.4rem;
      font-weight: 850;
      line-height: 1;
      letter-spacing: -0.04em;
    }

    .membership-weekly-price {
      margin-top: 0.45rem;
      color: var(--heather-dark);
      font-size: 1.22rem;
      font-weight: 850;
      line-height: 1.2;
    }

    .membership-cancel-note {
      max-width: none;
      margin: 1rem auto 0;
      padding: 0.85rem 1rem;
      border-radius: 16px;
      background: rgba(255, 255, 255, 0.72);
      color: var(--ink);
      font-size: 0.96rem;
      font-weight: 750;
      line-height: 1.45;
    }

    .membership-benefits-list {
      margin-top: 1.25rem;
      color: var(--muted);
    }

    .label {
      display: inline-block;
      margin-bottom: 1rem;
      padding: 0.32rem 0.68rem;
      border-radius: 999px;
      background: rgba(244, 166, 192, 0.72);
      color: white;
      font-size: 0.68rem;
      font-weight: 850;
      letter-spacing: 0.09em;
      text-transform: uppercase;
    }

    .popular {
      background: rgba(247, 216, 121, 0.72);
      color: var(--heather-dark);
    }

    .price-card ul {
      margin: 1.15rem 0 0;
      padding: 0;
      list-style: none;
      text-align: left;
    }

    .price-card li {
      position: relative;
      margin-bottom: 0.65rem;
      padding-left: 1.4rem;
      color: var(--ink);
      font-size: 0.98rem;
      line-height: 1.5;
    }

    .price-card li::before {
      content: "•";
      position: absolute;
      top: 0;
      left: 0;
      color: var(--summer-strawberry);
      font-weight: bold;
    }

    .small {
      padding: 0;
      color: var(--muted);
      font-size: 0.98rem;
      line-height: 1.55;
      text-align: left;
    }

    .small-note {
      margin: 0.9rem 0 0;
      color: var(--muted);
      font-size: 0.92rem;
      line-height: 1.45;
    }

    .membership-link-note {
      margin-top: 0.65rem;
      margin-bottom: 0;
      font-size: 0.86rem;
      line-height: 1.45;
      text-align: center;
    }

    #summer-pass,
    #calendar {
      scroll-margin-top: 2rem;
    }

    /* FAQ */

    .faq-list {
      display: grid;
      gap: 1rem;
      max-width: 850px;
      margin: 2.4rem auto 0;
      text-align: left;
    }

    .faq-item {
      padding: 1.45rem 1.6rem;
      border: 1px solid rgba(47, 79, 79, 0.08);
      border-radius: 22px;
      background: var(--cream);
    }

    .faq-item p {
      margin: 0;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.58;
    }

    .day-section {
      background: var(--beige);
    }

    /* Footer */

    .footer {
      padding: 4rem 1.5rem;
      background: var(--pale-blue);
      color: white;
    }

    .footer p {
      margin-bottom: 0.8rem;
      font-size: 0.95rem;
      opacity: 0.88;
    }

    .footer a {
      font-weight: 800;
    }

    .footer-social {
      margin-top: 1.4rem;
    }

    .footer-logo {
      display: block;
      width: auto;
      max-width: 260px;
      height: 88px;
      margin: -14px auto 1.2rem;
      object-fit: contain;
    }

    @media (max-width: 1000px) {
      .hero-inner,
      .content-split {
        grid-template-columns: 1fr;
        gap: 2rem;
      }

      .hero {
        padding: 2.5rem 1.25rem 0;
        text-align: center;
      }

      .hero-copy {
        padding: 1rem 0 2rem;
      }

      h1,
      .hero-subtitle {
        margin-left: auto;
        margin-right: auto;
      }

      .hero-actions {
        justify-content: center;
      }

      .photo-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .content-split {
        text-align: center;
      }

      .content-split > div,
      .content-split p {
        max-width: 720px;
        margin-left: auto;
        margin-right: auto;
      }
    }

    @media (max-width: 900px) {
      .included-grid,
      .reviews-grid {
        grid-template-columns: 1fr;
      }

      .location-visuals {
        grid-template-columns: 1fr;
        max-width: 620px;
      }

      .location-card {
        min-height: auto;
        aspect-ratio: 4 / 3;
      }

      .map-card {
        aspect-ratio: 4 / 5;
      }

      .calendar-summary {
        grid-template-columns: 1fr;
        gap: 1rem;
      }

      .calendar-pass-link {
        justify-self: start;
      }

      .footer-logo {
        max-width: 240px;
        height: 78px;
        margin: -12px auto 1.3rem;
      }
    }

    @media (max-width: 768px) {
      h1 {
        font-size: clamp(2.15rem, 11vw, 3.2rem);
        line-height: 1.02;
        letter-spacing: -0.055em;
      }

      h2 {
        font-size: clamp(1.8rem, 8vw, 2.45rem);
        line-height: 1.08;
      }

      h3 {
        font-size: 1.12rem;
      }

      p {
        font-size: 1rem;
        line-height: 1.62;
      }

      .section,
      .hero,
      .photo-story {
        padding-left: 1rem;
        padding-right: 1rem;
      }

      .section {
        padding-top: 3.2rem;
        padding-bottom: 3.2rem;
      }

      .hero-inner {
        gap: 1.25rem;
      }

      .logo img {
        display: block;
        width: 240px;
        max-width: 78vw;
        height: auto;
        margin: 0 auto 1.8rem;
      }

      .hero-subtitle {
        font-size: 1.12rem;
        line-height: 1.5;
      }

      .hero-photo {
        max-width: 100%;
        padding: 10px;
        border-width: 9px;
        border-radius: 30px;
        transform: none;
      }

      .hero-photo .photo {
        aspect-ratio: 4 / 5;
        height: auto;
        border-radius: 22px;
        object-fit: cover;
      }

      .photo,
      .story-photo {
        width: 100%;
        max-width: 100%;
        height: auto;
      }

      .photo {
        aspect-ratio: 4 / 3;
        margin: 1rem auto;
        border-width: 9px;
      }

      .story-photo {
        aspect-ratio: 4 / 5;
        border-width: 6px;
      }

      .photo-grid {
        grid-template-columns: 1fr;
        gap: 1rem;
      }

      .included-card,
      .price-card,
      .summer-offer-card,
      .faq-item,
      .review-card {
        padding: 1.35rem;
        border-radius: 22px;
      }

      /* Calendar */

      .weekly-calendar-section {
        padding-right: 0.75rem;
        padding-left: 0.75rem;
      }

      .calendar-legend {
        gap: 0.55rem 0.9rem;
        margin-bottom: 1.75rem;
      }

      .calendar-key {
        font-size: 0.78rem;
      }

      .week-calendar {
        min-width: 1435px;
      }

      .week-event {
        padding: 0.38rem 0.48rem;
      }

      .social-event {
        margin: 2px 0.4rem;
      }

      .availability-event {
        padding: 0.5rem;
      }

      .week-event-time {
        margin-bottom: 0.1rem;
        font-size: 0.62rem;
      }

      .week-event-title {
        font-size: 0.76rem;
        line-height: 1.04;
      }

      .week-event-extra {
        margin-top: 0.12rem;
        font-size: 0.52rem;
        line-height: 1.1;
      }

      .availability-event .week-event-time {
        font-size: 0.56rem;
      }

      .availability-event .week-event-title {
        font-size: 0.64rem;
      }

      /* Modal */

      .event-modal {
        padding: 0.75rem;
      }

      .event-modal-panel {
        width: min(520px, 100%);
        max-height: calc(100dvh - 1.5rem);
        padding: 1.4rem;
        border-radius: 22px;
      }

      .event-modal-panel h3 {
        font-size: 1.4rem;
      }

      .event-modal-description {
        font-size: 0.93rem;
        line-height: 1.45;
      }

      .event-modal-invitation {
        font-size: 0.89rem;
        line-height: 1.38;
      }

      .event-modal-actions .button {
        padding: 0.78rem 0.9rem;
        font-size: 0.88rem;
      }

      /* Press */

      .press-mentions {
        margin-top: 2.5rem;
        padding-top: 2.25rem;
        text-align: left;
      }

      .press-eyebrow,
      .press-intro {
        margin-left: 0;
        margin-right: 0;
        text-align: left;
      }

      .press-links {
        grid-template-columns: 1fr;
      }

      .press-link {
        min-height: 0;
        padding: 1.35rem;
        border-radius: 22px;
      }

      .press-title {
        font-size: 1.08rem;
      }

      /* Pricing */

      .summer-offer-card {
        max-width: 620px;
      }

      .reviews-section {
        padding-top: 3rem;
        padding-bottom: 3rem;
      }

      .reviews-section .content-wide,
      .pricing-section .content-wide {
        max-width: 100%;
      }

      .reviews-section h2,
      .reviews-section p,
      .reviews-section .eyebrow,
      .pricing-section h2,
      .pricing-section p,
      .pricing-section .eyebrow {
        margin-left: 0;
        margin-right: 0;
        text-align: left;
      }

      .reviews-section .section-intro,
      .pricing-section .section-intro {
        max-width: none;
        margin-bottom: 1.5rem;
      }

      .reviews-grid {
        display: block;
        max-width: 100%;
        margin-top: 1.5rem;
      }

      .review-card {
        width: 100%;
        margin: 0 0 1rem;
        padding: 1.25rem;
        border-radius: 22px;
      }

      .review-card p {
        margin-bottom: 0.9rem;
        font-size: 0.96rem;
        line-height: 1.55;
      }

      .membership-total {
        padding: 1rem;
        border-radius: 20px;
      }

      .membership-total-label {
        display: block;
        margin-bottom: 0.45rem;
        text-align: center;
      }

      .membership-total-price {
        font-size: 2.45rem;
        text-align: center;
      }

      .membership-weekly-price {
        font-size: 1.08rem;
        text-align: center;
      }

      .membership-cancel-note {
        padding: 0.8rem 0.85rem;
        font-size: 0.92rem;
        line-height: 1.42;
        text-align: center;
      }

      .membership-benefits-list {
        margin-top: 1rem;
      }

      .membership-benefits-list li {
        font-size: 0.94rem;
        line-height: 1.45;
      }

      button,
      .button {
        display: flex;
        width: 100%;
        max-width: 340px;
        margin: 1rem auto;
      }

      .week-event {
        display: block;
        width: auto;
        max-width: none;
        margin-top: 1px;
        margin-bottom: 1px;
      }

      .availability-event {
        display: flex;
        width: 100%;
        margin: 0;
      }

      .social-event {
        width: auto;
        margin-top: 2px;
        margin-bottom: 2px;
      }

      .event-modal-backdrop {
        display: block;
        width: 100%;
        max-width: none;
        margin: 0;
      }

      .event-modal-close {
        display: grid;
        width: 42px;
        max-width: 42px;
        margin: 0;
      }

      .hero-actions {
        width: 100%;
        gap: 0;
      }

      .summer-button {
        max-width: none;
        margin: 0.85rem 0 0;
      }

      .summer-sun {
        top: 1rem;
        right: 1rem;
        width: 48px;
        height: 48px;
      }

      .summer-strawberry-one,
      .summer-strawberry-two {
        display: none;
      }

      .wave {
        height: 72px;
        overflow: hidden;
      }

      .wave svg {
        width: 160%;
        margin-left: -30%;
      }

      .photo-strip {
        padding-right: 1rem;
        padding-bottom: 3rem;
        padding-left: 1rem;
        overflow: hidden;
      }

      .photo-strip .photo {
        width: 100%;
        max-width: 100%;
        height: auto;
        margin: 0 auto;
      }

      .footer {
        padding: 3.5rem 1rem;
        text-align: center;
      }

      .footer-logo {
        max-width: 240px;
        height: 78px;
        margin: -12px auto 1.4rem;
      }

      .footer p {
        max-width: 320px;
        margin-right: auto;
        margin-left: auto;
        overflow-wrap: anywhere;
        font-size: 0.95rem;
        line-height: 1.55;
        word-break: break-word;
      }
    }

    @media (max-width: 480px) {
      h1 {
        font-size: 2.25rem;
      }

      h2 {
        font-size: 1.9rem;
      }

      .eyebrow {
        font-size: 0.68rem;
        letter-spacing: 0.12em;
      }

      .logo img {
        width: 220px;
        max-width: 82vw;
        height: auto;
        margin: 0 auto 1.5rem;
      }

      .photo,
      .story-photo,
      .hero-photo .photo {
        aspect-ratio: auto;
      }

      .location-tagline {
        margin-bottom: 2rem;
      }

      .location-visuals {
        gap: 1rem;
      }

      .location-card {
        border-width: 9px;
        border-radius: 22px;
      }

      .map-card {
        aspect-ratio: 4 / 5;
      }

      /* Calendar */

      .week-event {
        padding: 0.34rem 0.4rem;
        border-radius: 10px;
      }

      .availability-event {
        padding: 0.42rem;
        border-radius: 11px;
      }

      .week-event-time {
        margin-bottom: 0.14rem;
        font-size: 0.6rem;
      }

      .week-event-title {
        font-size: 0.72rem;
        line-height: 1.08;
      }

      .availability-event .week-event-time {
        font-size: 0.56rem;
      }

      .availability-event .week-event-title {
        font-size: 0.64rem;
      }

      /* Modal */

      .event-modal {
        align-items: end;
        padding: 0.65rem;
      }

      .event-modal-panel {
        width: 100%;
        max-height: calc(100dvh - 1.3rem);
        padding: 1.25rem 1.1rem 1.1rem;
        border-radius: 22px;
      }

      .event-modal-close {
        top: 0.65rem;
        right: 0.65rem;
        width: 38px;
        height: 38px;
        min-width: 38px;
        max-width: 38px;
        font-size: 1.45rem;
      }

      .event-modal-time {
        margin-right: 2.8rem;
        font-size: 0.8rem;
      }

      .event-modal-panel h3 {
        margin-right: 2.8rem;
        font-size: 1.3rem;
      }

      .event-modal-access {
        margin-bottom: 0.85rem;
        font-size: 0.7rem;
      }

      .event-modal-description {
        font-size: 0.9rem;
        line-height: 1.42;
      }

      .event-modal-actions {
        gap: 0.6rem;
        margin-top: 0.85rem;
      }

      .event-modal-invitation {
        font-size: 0.86rem;
        line-height: 1.35;
      }

      .event-modal-actions .button {
        padding: 0.72rem 0.8rem;
        font-size: 0.85rem;
      }

      /* Remaining sections */

      .membership-total-price {
        font-size: 2.35rem;
      }

      .wave {
        height: 54px;
      }

      .wave svg {
        width: 190%;
        margin-left: -45%;
      }

      .photo-strip {
        padding-right: 0.75rem;
        padding-left: 0.75rem;
      }

      .review-card {
        padding: 1.1rem;
        border-radius: 20px;
      }

      .review-card p {
        font-size: 0.92rem;
        line-height: 1.52;
      }

      .review-card span {
        font-size: 0.74rem;
      }

      .summer-offer-card {
        padding: 1.2rem;
        border-radius: 22px;
      }

      .summer-offer-card h3 {
        font-size: 1.45rem;
      }

      .membership-total {
        padding: 0.95rem;
        border-radius: 18px;
      }

      .membership-weekly-price {
        font-size: 1rem;
      }

      .membership-cancel-note {
        padding: 0.75rem;
        font-size: 0.88rem;
      }

      .membership-benefits-list li {
        font-size: 0.92rem;
      }

      .footer {
        padding: 3rem 1rem;
      }

      .footer-logo {
        max-width: 220px;
        height: 72px;
        margin: -10px auto 1.3rem;
      }

      .footer p {
        max-width: 300px;
        font-size: 0.92rem;
      }
    }

    @media (max-height: 700px) {
      .event-modal-panel {
        padding-top: 1.1rem;
        padding-bottom: 1.1rem;
      }

      .event-modal-description {
        line-height: 1.4;
      }

      .event-modal-actions {
        gap: 0.55rem;
        margin-top: 0.75rem;
      }

      .event-modal-invitation {
        line-height: 1.35;
      }

      .event-modal-actions .button {
        padding-top: 0.68rem;
        padding-bottom: 0.68rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }

      .story-photo:hover,
      .press-link:hover,
      .calendar-pass-link:hover,
      button:hover,
      .button:hover {
        transform: none;
      }
    }
  `
}